def sum_of_digits(num):
  s = 0
  for dig in str(num):
    s += int(dig)
  return s

n = int(input())
base = 10 ** (len(str(n)) - 1)
ans = []
for num in range(base, n):
  check = sum_of_digits(num) + num
  if check > n:
    break
  elif check == n:
    ans.append(num)
print(len(ans))
for a in ans:
  print(a)

